update public.academy_modules set learning_objectives = array['Explain the purpose of a Job Description.', 'Identify the important sections of a JD.', 'Understand job titles and actual role responsibilities.', 'Separate mandatory requirements from preferred requirements.', 'Identify required qualifications and skills.', 'Evaluate experience requirements.', 'Understand location, work mode and shift requirements.', 'Convert a JD into a structured candidate profile.', 'Identify important screening points before sourcing.', 'Ask for clarification when a recruitment requirement is unclear.']::text[] where module_number = 2;
insert into public.lessons (module_id, sort_order, title, description, content_type, estimated_minutes, is_required, status, content)
select id, 1, 'Introduction to Job Descriptions', 'What a JD is, why it matters and how to read one before sourcing.', 'text', 12, true, 'active', '{"blocks": [{"type": "h", "text": "What is a Job Description?"}, {"type": "p", "text": "A Job Description (JD) is the written requirement from the client or hiring manager. It explains what the role is, what the person will do and what the person must bring. For a recruiter, the JD is the starting point of every search."}, {"type": "h", "text": "Purpose of a JD"}, {"type": "list", "items": ["Defines the role and its responsibilities.", "States the skills, qualification and experience required.", "Sets conditions such as location, work mode, shift and salary range.", "Gives the recruiter and the hiring team one shared reference."]}, {"type": "h", "text": "Why recruiters must understand a JD before sourcing"}, {"type": "p", "text": "If you source before you understand the requirement, you send unsuitable profiles, waste the candidate''s time and lose the hiring manager''s trust. Ten minutes spent decoding the JD saves hours of wrong calls."}, {"type": "h", "text": "Main sections of a JD"}, {"type": "terms", "items": [{"term": "Job title", "definition": "The name of the position, e.g. Inside Sales Executive."}, {"term": "About the role / summary", "definition": "One or two lines on why the role exists."}, {"term": "Responsibilities", "definition": "The actual day-to-day work."}, {"term": "Requirements", "definition": "Qualification, skills and experience — usually split into must-have and preferred."}, {"term": "Job details", "definition": "Location, work mode, shift, CTC range, notice period, number of openings."}, {"term": "About the company", "definition": "Context you can use when pitching the role."}]}, {"type": "h", "text": "Example JD"}, {"type": "example", "title": "Sample JD — Inside Sales Executive (original training example)", "text": "Location: Bengaluru (Whitefield), work from office, day shift 9:30–6:30. Openings: 3. Responsibilities: call inbound and outbound leads for a B2B software product, qualify prospects, book demos for the field team, update the CRM daily. Must have: graduate in any discipline, 1–3 years of B2B inside sales or telesales, fluent English and Kannada or Hindi. Preferred: CRM experience (Zoho or Salesforce), SaaS selling exposure. CTC: up to 4.5 LPA fixed plus incentives. Notice period: immediate to 30 days."}, {"type": "terms", "items": [{"term": "Title", "definition": "Inside Sales Executive — a phone-based sales role, not field sales."}, {"term": "Responsibilities", "definition": "Lead qualification and demo booking; the person does not close large deals."}, {"term": "Must have", "definition": "Graduate, 1–3 years B2B inside/telesales, English plus Kannada or Hindi."}, {"term": "Preferred", "definition": "CRM tools and SaaS exposure — useful, but not a reason to reject."}, {"term": "Job details", "definition": "Bengaluru office, day shift, 3 openings, up to 4.5 LPA, join within 30 days."}]}, {"type": "h", "text": "Job title vs actual responsibilities"}, {"type": "p", "text": "Titles are short labels; responsibilities describe the real work. Always read the responsibilities before deciding which candidates fit."}, {"type": "h", "text": "Mandatory vs preferred"}, {"type": "compare", "title": "How to treat requirements", "good": "Mandatory: the candidate must meet it. Missing it usually means the profile is not suitable.", "bad": "Preferred: an advantage. A candidate without it can still be shortlisted.", "goodLabel": "Mandatory", "badLabel": "Preferred"}, {"type": "h", "text": "How a recruiter should read a JD"}, {"type": "steps", "items": [{"title": "Read it fully once", "text": "Do not stop at the title."}, {"title": "Mark the must-haves", "text": "Underline qualification, core skills and minimum experience."}, {"title": "Mark the conditions", "text": "Location, work mode, shift, CTC, notice period, openings."}, {"title": "List what is unclear", "text": "Anything vague becomes a question for the hiring manager."}, {"title": "Summarise in one line", "text": "e.g. ''Graduate with 1–3 yrs B2B telesales, Bengaluru office, join in 30 days.''"}]}, {"type": "callout", "text": "If you cannot summarise the requirement in one sentence, you are not ready to source yet."}]}'::jsonb from public.academy_modules where module_number = 2
