select id, 2, 'Understanding Job Titles and Roles', 'Titles, roles, seniority and why the same job appears under different names.', 'text', 14, true, 'active', '{"blocks": [{"type": "h", "text": "Key terms"}, {"type": "terms", "items": [{"term": "Job title", "definition": "The label on the JD or offer letter."}, {"term": "Role", "definition": "The work the person actually does."}, {"term": "Department", "definition": "The team the role sits in — Sales, Engineering, HR, Support."}, {"term": "Seniority", "definition": "Level in the hierarchy: executive, senior executive, lead, manager."}, {"term": "Experience level", "definition": "Years and depth of relevant work expected for the role."}]}, {"type": "h", "text": "Common title variations"}, {"type": "p", "text": "Companies name the same work differently. Search for all common variations, not just the title on the JD."}, {"type": "terms", "items": [{"term": "Software Developer / Software Engineer", "definition": "Usually the same work: writing, testing and maintaining code. Check the tech stack, not the word ''developer'' or ''engineer''."}, {"term": "Business Development Executive / Sales Executive", "definition": "Both sell. BDE roles often focus on finding new clients; Sales Executive may handle existing accounts or walk-in sales."}, {"term": "HR Recruiter / Talent Acquisition Executive", "definition": "Both source and screen candidates. ''Talent Acquisition'' is often used in corporates; the daily work is similar."}, {"term": "Customer Support Executive", "definition": "May also appear as Customer Service Associate, Customer Care Executive or Process Associate (voice/non-voice)."}]}, {"type": "h", "text": "Why the same role has different titles"}, {"type": "list", "items": ["Company size — a startup ''Manager'' may equal a large company ''Senior Executive''.", "Industry habits — BPOs use ''Associate'', IT uses ''Engineer''.", "Internal grading systems.", "Titles used to attract candidates."]}, {"type": "h", "text": "Understanding the work behind a title"}, {"type": "example", "title": "Scenario", "text": "A JD says ''Business Development Executive'', but the responsibilities are: answer inbound queries, explain course fees to students on the phone, enrol them. The real role is inbound telesales/counselling. Searching only for ''BDE'' with field-sales experience would bring the wrong profiles."}, {"type": "compare", "title": "Title-only vs responsibility-based sourcing", "good": "Search by the work: ''inbound calls'', ''counselling'', ''enrolment'', plus title variations.", "bad": "Search only for the exact title ''Business Development Executive''.", "goodLabel": "Do", "badLabel": "Avoid"}, {"type": "callout", "text": "Never shortlist or reject on title alone. Ask the candidate what they did day to day and compare it with the JD responsibilities."}]}'::jsonb from public.academy_modules where module_number = 2
