select id, 3, 'Decoding Skills and Qualifications', 'Separating qualifications and skills into must-have and good-to-have.', 'scenario', 18, true, 'active', '{"blocks": [{"type": "h", "text": "What to identify in every JD"}, {"type": "terms", "items": [{"term": "Educational qualification", "definition": "Degree or diploma required, e.g. B.Com, B.E./B.Tech, any graduate."}, {"term": "Technical skills", "definition": "Tools or technologies, e.g. Java, Tally, Excel, SAP MM."}, {"term": "Functional skills", "definition": "Job knowledge, e.g. accounts payable, vendor negotiation, lead qualification."}, {"term": "Soft skills", "definition": "Communication, language fluency, customer handling, teamwork."}, {"term": "Certifications", "definition": "Formal certificates, e.g. AWS Certified, CA Inter, Six Sigma Green Belt."}, {"term": "Experience", "definition": "Minimum years of relevant work."}, {"term": "Industry/domain experience", "definition": "Background in a specific sector, e.g. manufacturing, BFSI, healthcare."}]}, {"type": "h", "text": "Must have vs good to have"}, {"type": "compare", "title": "Read the wording carefully", "good": "Must have: ''required'', ''mandatory'', ''must'', ''minimum'', ''should have''.", "bad": "Good to have: ''preferred'', ''plus'', ''added advantage'', ''nice to have'', ''exposure to''.", "goodLabel": "Must have", "badLabel": "Good to have"}, {"type": "h", "text": "Scenario JD — Accounts Executive (original training example)"}, {"type": "example", "title": "JD extract", "text": "B.Com or M.Com required. 2–4 years in accounts payable / receivable. Must be hands-on with Tally Prime and GST filing. Advanced Excel (VLOOKUP, pivot tables) required. SAP FICO exposure is an added advantage. Manufacturing industry background preferred. Good written English."}, {"type": "terms", "items": [{"term": "Qualification (must)", "definition": "B.Com or M.Com."}, {"term": "Experience (must)", "definition": "2–4 years AP/AR."}, {"term": "Technical (must)", "definition": "Tally Prime, GST filing, advanced Excel."}, {"term": "Technical (preferred)", "definition": "SAP FICO."}, {"term": "Domain (preferred)", "definition": "Manufacturing."}, {"term": "Soft skill", "definition": "Good written English — confirm with the hiring manager how strictly this is assessed."}]}, {"type": "h", "text": "How to use this"}, {"type": "steps", "items": [{"title": "Build your search", "text": "Use must-haves as search keywords: ''Tally Prime'', ''GST'', ''accounts payable''."}, {"title": "Screen", "text": "Confirm every must-have on the call; do not assume from the CV."}, {"title": "Rank", "text": "Candidates with preferred skills move higher, but are not the only ones shortlisted."}]}, {"type": "callout", "text": "If a JD lists ten ''mandatory'' skills, ask the hiring manager which three are truly non-negotiable. Very long must-have lists often hide a few real priorities."}]}'::jsonb from public.academy_modules where module_number = 2
