select id, 4, 'Understanding Experience Requirements', 'Total vs relevant experience, levels, gaps and availability.', 'scenario', 16, true, 'active', '{"blocks": [{"type": "h", "text": "Types of experience"}, {"type": "terms", "items": [{"term": "Total experience", "definition": "All years of work, in any role."}, {"term": "Relevant experience", "definition": "Years doing work that matches this JD."}, {"term": "Industry experience", "definition": "Years in the same sector as the client."}, {"term": "Role-specific experience", "definition": "Years in the same function and level, e.g. ''team lead in voice process''."}]}, {"type": "h", "text": "Experience levels"}, {"type": "terms", "items": [{"term": "Fresher", "definition": "No full-time work experience; internships may count."}, {"term": "Entry-level", "definition": "Around 0–2 years."}, {"term": "Mid-level", "definition": "Around 3–7 years, works independently."}, {"term": "Senior-level", "definition": "Around 8+ years, leads people or complex work."}]}, {"type": "p", "text": "Ranges vary by company — always follow the range written in the JD."}, {"type": "h", "text": "Other factors to check"}, {"type": "terms", "items": [{"term": "Career gaps", "definition": "Ask politely and neutrally for the reason; a gap is not automatically a rejection. Record facts, not opinions."}, {"term": "Notice period", "definition": "How long before the candidate can join."}, {"term": "Current employment status", "definition": "Employed, serving notice, or currently not working — affects joining date."}]}, {"type": "h", "text": "Comparing candidate experience with the JD"}, {"type": "example", "title": "Scenario 1", "text": "JD: 3–5 years Java backend development. Candidate: 6 years total — 2 years manual testing, 4 years Java backend. Relevant experience is 4 years — a match, even though total is 6."}, {"type": "example", "title": "Scenario 2", "text": "JD: 2+ years customer support in international voice process. Candidate: 3 years domestic chat support. Total experience fits, but relevant experience (international voice) is zero — not a match unless the hiring manager agrees."}, {"type": "example", "title": "Scenario 3", "text": "JD: 1–3 years. Candidate: 5 years. Over-experience can mean salary mismatch or quick attrition. Check expectations before shortlisting and flag it to the hiring manager."}, {"type": "callout", "text": "Always write relevant experience separately from total experience in your notes — hiring managers ask for it."}]}'::jsonb from public.academy_modules where module_number = 2
