select id, 5, 'Understanding Location, Work Mode and Shift', 'How location, work mode, shift and travel affect who you source.', 'text', 15, true, 'active', '{"blocks": [{"type": "h", "text": "Location terms"}, {"type": "terms", "items": [{"term": "Job location", "definition": "Where the employee will work, e.g. Pune — Hinjewadi."}, {"term": "Candidate location", "definition": "Where the candidate lives now."}, {"term": "Local candidate", "definition": "Already living within commuting distance."}, {"term": "Relocation", "definition": "Candidate is willing to move; confirm timeline and whether support is offered."}, {"term": "Joining location", "definition": "Where the candidate reports on day one — can differ from the posting location for training."}]}, {"type": "h", "text": "Work mode"}, {"type": "terms", "items": [{"term": "Work from office", "definition": "Full-time at the client location."}, {"term": "Hybrid", "definition": "Mix of office and home — confirm the number of office days."}, {"term": "Remote", "definition": "Fully from home — confirm laptop, internet and any state/country limits."}]}, {"type": "h", "text": "Shifts"}, {"type": "terms", "items": [{"term": "Day shift", "definition": "Standard daytime hours."}, {"term": "Night shift", "definition": "Often for US/UK processes; check transport and allowances."}, {"term": "Rotational shift", "definition": "Timings change weekly or monthly; candidate must be flexible."}, {"term": "Travel requirement", "definition": "Percentage of time on the road or at client sites."}]}, {"type": "h", "text": "How these affect sourcing"}, {"type": "list", "items": ["Filter searches by location and nearby areas first.", "State work mode and shift in your first message to save time.", "Night or rotational shifts reduce the pool — start sourcing earlier.", "For relocation, confirm the candidate''s real willingness, not just ''open to relocate'' on a portal."]}, {"type": "h", "text": "Recruiter scenarios"}, {"type": "example", "title": "Scenario 1", "text": "Role: Hyderabad, WFO, rotational shift. A strong candidate in Vijayawada says ''I can relocate''. Ask when, whether they have arranged accommodation, and confirm they accept rotational shifts before shortlisting."}, {"type": "example", "title": "Scenario 2", "text": "JD says ''Hybrid''. The candidate asks how many days in office. If the JD does not say, do not guess — check with the hiring manager and reply."}, {"type": "callout", "text": "Most early drop-outs come from location, shift or work-mode surprises. Confirm all three on the first call."}]}'::jsonb from public.academy_modules where module_number = 2
