select id, 6, 'Salary, Notice Period and Other Candidate Requirements', 'CTC, availability, eligibility and communicating requirements accurately.', 'text', 17, true, 'active', '{"blocks": [{"type": "h", "text": "Compensation terms"}, {"type": "terms", "items": [{"term": "CTC", "definition": "Cost to Company — total yearly cost including fixed pay, variable pay and benefits."}, {"term": "Expected salary", "definition": "What the candidate wants for the new role."}, {"term": "Current salary", "definition": "Ask only when relevant to the role and allowed by company policy and applicable law; record it accurately and keep it confidential."}, {"term": "Fixed vs variable", "definition": "Clarify how much of the CTC is guaranteed."}]}, {"type": "h", "text": "Availability"}, {"type": "terms", "items": [{"term": "Notice period", "definition": "Time the candidate must serve at their current employer."}, {"term": "Immediate joiner", "definition": "Can join within a few days."}, {"term": "Joining timeline", "definition": "The client''s target start date."}, {"term": "Availability", "definition": "When the candidate can attend interviews."}]}, {"type": "h", "text": "Eligibility and other requirements"}, {"type": "list", "items": ["Work authorisation or eligibility where applicable (e.g. right to work in a country).", "Documents needed for background verification.", "Role-specific needs: two-wheeler and licence for field roles, a language test, a typing speed.", "Willingness for night shift or travel."]}, {"type": "h", "text": "Practical examples"}, {"type": "example", "title": "Example 1", "text": "JD: up to 6 LPA. Candidate expects 7.5 LPA. Do not say ''that should be fine''. Say: ''The approved range is up to 6 LPA. I will share your expectation with the hiring team, but I cannot confirm any number.''"}, {"type": "example", "title": "Example 2", "text": "Client needs joining within 15 days. Candidate has a 60-day notice with no buyout. Record it and inform the hiring manager before scheduling — do not hide it to fill the slot."}, {"type": "h", "text": "Avoid unauthorised promises"}, {"type": "compare", "title": "What you say to candidates", "good": "''The final offer depends on the interview outcome and the hiring team''s approval.''", "bad": "''You will definitely get 30% hike'' or ''the job is confirmed''.", "goodLabel": "Say", "badLabel": "Never say"}, {"type": "callout", "text": "Only the employer can make an offer. Your role is to communicate confirmed information accurately and record what the candidate tells you."}]}'::jsonb from public.academy_modules where module_number = 2
