select id, 7, 'JD Decoding: Mandatory vs Preferred', 'Practice exercise: decode a sample JD, then review the correct interpretation.', 'practice', 20, true, 'active', '{"blocks": [{"type": "h", "text": "Exercise instructions"}, {"type": "p", "text": "Read the JD below. On paper or in a notepad, identify each item in the checklist. When you have finished, open the correct interpretation and compare."}, {"type": "example", "title": "Sample JD — Customer Support Associate, International Voice (original training example)", "text": "Company: a travel-services client of E2E Procurement. Openings: 10. Location: Noida Sector 62, work from office. Shift: rotational night shifts (US hours), 5 days a week, two rotational offs. Responsibilities: handle inbound calls from US customers about bookings, changes and refunds; resolve queries using the internal tool; log every call. Requirements: graduate or undergraduate with at least 6 months of international voice experience; excellent spoken English with neutral accent; comfortable with night shifts. Preferred: travel or airline process experience; basic computer skills and typing 25+ WPM. Salary: 3.0–4.2 LPA plus night-shift allowance and cab facility. Notice period: immediate joiners preferred, up to 15 days acceptable."}, {"type": "h", "text": "Checklist — identify these"}, {"type": "list", "items": ["Job title", "Required qualification", "Mandatory skills", "Preferred skills", "Required experience", "Location", "Work mode", "Shift", "Salary information", "Notice period", "Number of openings", "Key candidate profile"]}, {"type": "answer", "title": "Correct interpretation", "items": [{"term": "Job title", "definition": "Customer Support Associate — International Voice."}, {"term": "Required qualification", "definition": "Graduate or undergraduate (undergraduates accepted)."}, {"term": "Mandatory skills", "definition": "Excellent spoken English with neutral accent; willingness for night shifts."}, {"term": "Preferred skills", "definition": "Travel/airline process experience; basic computer skills; typing 25+ WPM."}, {"term": "Required experience", "definition": "Minimum 6 months of international voice — domestic voice or chat does not count."}, {"term": "Location", "definition": "Noida Sector 62."}, {"term": "Work mode", "definition": "Work from office."}, {"term": "Shift", "definition": "Rotational night shifts, US hours, 5 days, rotational offs."}, {"term": "Salary information", "definition": "3.0–4.2 LPA plus night-shift allowance and cab."}, {"term": "Notice period", "definition": "Immediate preferred; maximum 15 days."}, {"term": "Number of openings", "definition": "10."}, {"term": "Key candidate profile", "definition": "Delhi-NCR based communicator with 6+ months international voice, fluent English, ready for night shifts and able to join within 15 days."}]}, {"type": "callout", "text": "Common mistakes: treating ''travel process experience'' as mandatory, and counting domestic chat experience as international voice."}]}'::jsonb from public.academy_modules where module_number = 2
