select id, 8, 'Convert a JD into a Candidate Profile', 'Practice exercise: turn a requirement into a structured profile for sourcing and screening.', 'practice', 19, true, 'active', '{"blocks": [{"type": "h", "text": "Why build a candidate profile"}, {"type": "p", "text": "A candidate profile is a one-page summary of the ideal candidate. It becomes your search brief while sourcing and your checklist while screening, so every recruiter on the requirement looks for the same person."}, {"type": "h", "text": "The requirement (original training example)"}, {"type": "example", "title": "Email from the hiring manager", "text": "We need 2 Procurement Executives for our Chennai (Guindy) plant, office-based, general shift 9–6, Monday to Saturday. They will raise purchase orders in SAP, follow up with vendors on delivery, compare quotations and maintain vendor records. Engineering diploma or any graduate is fine. Need 2–5 years in procurement or purchase in a manufacturing company — SAP MM is a must. Knowledge of Tamil helps with local vendors. Budget is up to 5.5 LPA. We need people within 30 days."}, {"type": "h", "text": "Exercise"}, {"type": "p", "text": "Using the email, fill in the 14 fields below. Then open the model answer."}, {"type": "list", "items": ["1. Target job title", "2. Qualification", "3. Mandatory skills", "4. Preferred skills", "5. Experience", "6. Industry/domain", "7. Location", "8. Work mode", "9. Shift", "10. Salary/CTC", "11. Notice period", "12. Joining requirement", "13. Candidate source strategy", "14. Key screening points"]}, {"type": "answer", "title": "Model candidate profile", "items": [{"term": "1. Target job title", "definition": "Procurement Executive (search also: Purchase Executive, Buyer, Purchase Officer)."}, {"term": "2. Qualification", "definition": "Engineering diploma or any graduate."}, {"term": "3. Mandatory skills", "definition": "SAP MM (PO creation), vendor follow-up, quotation comparison, vendor record maintenance."}, {"term": "4. Preferred skills", "definition": "Tamil for local vendor communication."}, {"term": "5. Experience", "definition": "2–5 years relevant procurement/purchase experience."}, {"term": "6. Industry/domain", "definition": "Manufacturing — mandatory per the email."}, {"term": "7. Location", "definition": "Chennai, Guindy plant; prefer candidates in South/West Chennai."}, {"term": "8. Work mode", "definition": "Work from office."}, {"term": "9. Shift", "definition": "General shift 9–6, Monday to Saturday (6 days)."}, {"term": "10. Salary/CTC", "definition": "Up to 5.5 LPA."}, {"term": "11. Notice period", "definition": "Maximum 30 days."}, {"term": "12. Joining requirement", "definition": "Join within 30 days; 2 openings."}, {"term": "13. Candidate source strategy", "definition": "Job portals with keywords ''SAP MM'' + ''purchase'' + ''manufacturing'' filtered to Chennai; professional networks; referrals from placed procurement candidates; internal database."}, {"term": "14. Key screening points", "definition": "Hands-on SAP MM (ask what transactions they use), manufacturing background, comfort with 6-day week, current location and commute to Guindy, notice period ≤30 days, CTC expectation within 5.5 LPA."}]}, {"type": "h", "text": "Clarify before sourcing"}, {"type": "list", "items": ["Is Saturday a full working day?", "Is 5.5 LPA fixed or including variable?", "Would a trading-company buyer with strong SAP MM be considered?"]}, {"type": "callout", "text": "Share your profile with the hiring manager before sourcing. A 2-minute confirmation prevents a week of wrong submissions."}]}'::jsonb from public.academy_modules where module_number = 2
